import { useEffect, useRef, useState } from "react";
import type { RevealStyle } from "../content";
import BurnReveal from "./burnReveal";
import { playReveal } from "./sfx";

/**
 * 상세 페이지에 처음 들어갈 때 화면을 덮었다가 걷어내는 연출.
 * 각 연출은 "아직 덮고 있는 부분"만 그리고, 다 걷히면 캔버스를 없앤다.
 * 클릭은 통과하고, 동작 줄이기 설정이면 건너뛴다. (burn 은 burnReveal.tsx)
 */

type Draw = (ctx: CanvasRenderingContext2D, w: number, h: number, t: number) => boolean;
/** 연출이 페이지에 주는 효과 (예: 임팩트 순간 화면 흔들기) */
interface RevealHooks {
    shake: () => void;
}
type Factory = (w: number, h: number, accent: string, fx: RevealHooks) => Draw;

const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x);
const easeIn = (x: number) => x * x * x;
const easeInOut = (x: number) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
const rand = (a: number, b: number) => a + Math.random() * (b - a);

/**
 * 발!도!!: 발도 일섬.
 * 기 모으기(칼끝 반짝임) → 0.06초 만에 화면을 가르는 일섬 → 흰 섬광 + 히트스톱 + 불꽃
 * → 화면 흔들림과 함께 두 조각이 기울며 빠르게 갈라진다.
 */
const slash: Factory = (w, h, accent, fx) => {
    const angle = Math.atan2(-h * 0.62, w); // 왼쪽 아래 → 오른쪽 위
    const diag = Math.hypot(w, h);
    const cos = Math.cos(angle), sin = Math.sin(angle);
    const T_CHARGE = 0.2; // 기 모으기
    const T_CUT = 0.06; // 일섬
    const T_HIT = T_CHARGE + T_CUT; // 임팩트 순간
    const T_STOP = 0.11; // 히트스톱
    const T_OPEN = 0.55; // 갈라지는 시간
    // 화면 좌표의 베기 선 (중심 기준 회전 좌표계에서 x = -diag/2 ~ diag/2, y = 0)
    const toScreen = (lx: number, ly: number) => ({ x: w / 2 + lx * cos - ly * sin, y: h / 2 + lx * sin + ly * cos });

    interface Spark { x: number; y: number; vx: number; vy: number; life: number; max: number; hot: boolean }
    const sparks: Spark[] = [];
    let impacted = false;
    let last = 0;

    return (ctx, _w, _h, t) => {
        const dt = Math.min(0.05, Math.max(0, t - last));
        last = t;
        const cut = clamp01((t - T_CHARGE) / T_CUT);
        const openP = clamp01((t - T_HIT - T_STOP) / T_OPEN);
        const open = 1 - Math.pow(1 - openP, 5); // 아주 빠르게 열리고 천천히 멈춘다
        const off = open * diag * 0.5;
        const tilt = open * 0.045;

        // 임팩트: 불꽃을 터뜨리고 페이지를 흔든다 (한 번만)
        if (!impacted && t >= T_HIT) {
            impacted = true;
            fx.shake();
            for (let i = 0; i < 90; i++) {
                const along = rand(-0.48, 0.48) * diag;
                const side = Math.random() < 0.5 ? -1 : 1;
                const sp = rand(250, 900);
                const spread = rand(-0.9, 0.9);
                const p = toScreen(along, 0);
                // 베기 선에 수직인 방향 + 진행 방향으로 조금
                const nx = -sin * side, ny = cos * side;
                sparks.push({
                    x: p.x,
                    y: p.y,
                    vx: (nx + cos * spread) * sp,
                    vy: (ny + sin * spread) * sp,
                    life: 0,
                    max: rand(0.25, 0.7),
                    hot: Math.random() < 0.4,
                });
            }
        }

        // 1) 덮개: 두 조각 (갈라지면서 살짝 기운다)
        ctx.save();
        ctx.translate(w / 2, h / 2);
        ctx.rotate(angle);
        const big = diag * 2;
        const dark = "#0d0a07";
        for (const side of [-1, 1] as const) {
            ctx.save();
            ctx.translate(0, side * off);
            ctx.rotate(side * tilt);
            ctx.fillStyle = dark;
            ctx.fillRect(-big / 2, side < 0 ? -big / 2 : 0, big, big / 2);
            // 베인 단면이 잠깐 달아올라 빛난다
            if (impacted && openP < 1) {
                const glow = Math.max(0, 1 - openP * 1.4);
                ctx.globalAlpha = glow;
                ctx.fillStyle = accent;
                ctx.fillRect(-big / 2, side < 0 ? -4 : 0, big, 4);
                ctx.fillStyle = "#fff6dc";
                ctx.fillRect(-big / 2, side < 0 ? -1.5 : 0, big, 1.5);
                ctx.globalAlpha = 1;
            }
            ctx.restore();
        }

        // 2) 기 모으기: 칼끝 반짝임
        if (t < T_CHARGE + 0.02) {
            const k = clamp01(t / T_CHARGE);
            ctx.globalCompositeOperation = "lighter";
            ctx.fillStyle = accent;
            ctx.globalAlpha = 0.25 + 0.75 * k;
            const L = 8 + 70 * k * k; // 반짝임 십자 길이
            ctx.fillRect(-diag / 2 + 30 - L, -1.5, L * 2, 3);
            ctx.fillRect(-diag / 2 + 30 - 1.5, -L * 0.45, 3, L * 0.9);
            ctx.fillStyle = "#fff";
            ctx.fillRect(-diag / 2 + 26, -4, 8, 8);
            ctx.globalAlpha = 1;
            ctx.globalCompositeOperation = "source-over";
        }

        // 3) 일섬: 굵은 빛 + 잔상
        if (cut > 0 && openP < 0.3) {
            const fade = t < T_HIT + T_STOP ? 1 : Math.max(0, 1 - openP / 0.3);
            const len = diag * cut;
            ctx.globalCompositeOperation = "lighter";
            ctx.fillStyle = accent;
            ctx.globalAlpha = fade * 0.18;
            ctx.fillRect(-diag / 2, -46, len, 92); // 넓은 잔광
            ctx.globalAlpha = fade * 0.45;
            ctx.fillRect(-diag / 2, -14, len, 28);
            ctx.globalAlpha = fade;
            ctx.fillRect(-diag / 2, -6, len, 12);
            ctx.fillStyle = "#ffffff";
            ctx.fillRect(-diag / 2, -2.5, len, 5);
            // 칼날 끝
            if (cut < 1) {
                ctx.fillRect(-diag / 2 + len - 24, -9, 24, 18);
            }
            ctx.globalAlpha = 1;
            ctx.globalCompositeOperation = "source-over";
        }
        ctx.restore();

        // 4) 임팩트 섬광 (히트스톱 동안 화면 전체가 하얗게 번쩍)
        if (impacted) {
            const fl = 1 - clamp01((t - T_HIT) / 0.16);
            if (fl > 0) {
                ctx.globalAlpha = 0.85 * fl * fl;
                ctx.fillStyle = "#fff8e8";
                ctx.fillRect(0, 0, w, h);
                ctx.globalAlpha = 1;
            }
        }

        // 5) 불꽃: 속도 방향으로 늘어진 짧은 선
        if (sparks.length) {
            ctx.globalCompositeOperation = "lighter";
            ctx.lineCap = "round";
            const frozen = t < T_HIT + T_STOP; // 히트스톱 동안은 멈춰 있다
            for (let i = sparks.length - 1; i >= 0; i--) {
                const s = sparks[i];
                if (!frozen) {
                    s.life += dt;
                    s.x += s.vx * dt;
                    s.y += s.vy * dt;
                    s.vx *= 0.9;
                    s.vy = s.vy * 0.9 + 900 * dt;
                }
                if (s.life >= s.max) {
                    sparks.splice(i, 1);
                    continue;
                }
                const a = 1 - s.life / s.max;
                ctx.globalAlpha = a;
                ctx.strokeStyle = s.hot ? "#fffbe8" : accent;
                ctx.lineWidth = s.hot ? 2.5 : 1.8;
                ctx.beginPath();
                ctx.moveTo(s.x, s.y);
                ctx.lineTo(s.x - s.vx * 0.03, s.y - s.vy * 0.03);
                ctx.stroke();
            }
            ctx.globalAlpha = 1;
            ctx.globalCompositeOperation = "source-over";
        }

        return openP < 1 || sparks.length > 0;
    };
};

/** 제발 꺼져 용사야!: 화면을 덮은 마법 카드 뒷면이 가운데부터 뒤집혀 사라진다 */
const cards: Factory = (w, h, accent) => {
    const cols = Math.max(4, Math.round(w / 92));
    const rows = Math.max(3, Math.round(h / 128));
    const cw = w / cols, ch = h / rows;
    const cx = w / 2, cy = h / 2, maxD = Math.hypot(cx, cy);
    const list: { x: number; y: number; delay: number }[] = [];
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++) {
            const x = c * cw, y = r * ch;
            const d = Math.hypot(x + cw / 2 - cx, y + ch / 2 - cy) / maxD;
            list.push({ x, y, delay: 0.1 + d * 0.75 + rand(0, 0.08) });
        }
    return (ctx, _w, _h, t) => {
        let alive = false;
        for (const k of list) {
            const p = clamp01((t - k.delay) / 0.42);
            if (p >= 1) continue;
            alive = true;
            const sx = Math.abs(Math.cos((p * Math.PI) / 2)); // 뒤집히며 폭이 줄어든다
            const lift = 1 + p * 0.12;
            const ww = cw * sx * lift, hh = ch * lift;
            const x = k.x + (cw - ww) / 2, y = k.y + (ch - hh) / 2 - p * 10;
            ctx.globalAlpha = 1 - easeIn(p) * 0.6;
            ctx.fillStyle = "#1a0f24";
            ctx.fillRect(x + 1, y + 1, ww - 2, hh - 2);
            ctx.strokeStyle = accent;
            ctx.lineWidth = 2;
            ctx.strokeRect(x + 4, y + 4, ww - 8, hh - 8);
            // 가운데 마름모 문양
            if (ww > 16) {
                const mx = x + ww / 2, my = y + hh / 2, s = Math.min(ww, hh) * 0.18;
                ctx.fillStyle = "#3a1d52";
                ctx.beginPath();
                ctx.moveTo(mx, my - s * 1.4);
                ctx.lineTo(mx + s, my);
                ctx.lineTo(mx, my + s * 1.4);
                ctx.lineTo(mx - s, my);
                ctx.closePath();
                ctx.fill();
                ctx.stroke();
            }
        }
        ctx.globalAlpha = 1;
        return alive;
    };
};

/** 하늘오름: 별이 바깥으로 쏟아지는 워프 → 빛 고리가 퍼지며 열린다 */
const warp: Factory = (w, h, accent) => {
    const cx = w / 2, cy = h * 0.55, diag = Math.hypot(w, h);
    const stars = Array.from({ length: 160 }, () => ({ a: rand(0, Math.PI * 2), d: rand(0.02, 1), s: rand(0.6, 1.8) }));
    return (ctx, _w, _h, t) => {
        const iris = easeIn(clamp01((t - 0.55) / 0.85)) * diag * 1.05;
        // 덮개 + 별 줄기
        ctx.fillStyle = "#04060f";
        ctx.fillRect(0, 0, w, h);
        const speed = easeIn(clamp01(t / 0.9));
        ctx.globalCompositeOperation = "lighter";
        ctx.globalAlpha = 0.5 + 0.5 * speed;
        ctx.lineWidth = 1.4;
        for (const [color, big] of [["#dfe9ff", false], [accent, true]] as const) {
            ctx.strokeStyle = color;
            ctx.beginPath();
            for (const s of stars) {
                if ((s.s > 1.3) !== big) continue;
                const r0 = (s.d + speed * 1.6 * s.s) * diag * 0.5;
                const len = 4 + speed * 140 * s.s;
                ctx.moveTo(cx + Math.cos(s.a) * r0, cy + Math.sin(s.a) * r0);
                ctx.lineTo(cx + Math.cos(s.a) * (r0 + len), cy + Math.sin(s.a) * (r0 + len));
            }
            ctx.stroke();
        }
        ctx.globalAlpha = 1;
        // 가운데부터 뚫린다 (부드러운 가장자리)
        if (iris > 0) {
            ctx.globalCompositeOperation = "destination-out";
            const g = ctx.createRadialGradient(cx, cy, iris * 0.85, cx, cy, iris + 1);
            g.addColorStop(0, "rgba(0,0,0,1)");
            g.addColorStop(1, "rgba(0,0,0,0)");
            ctx.fillStyle = g;
            ctx.beginPath();
            ctx.arc(cx, cy, iris + 1, 0, Math.PI * 2);
            ctx.fill();
            // 빛 고리
            ctx.globalCompositeOperation = "lighter";
            const ringA = Math.max(0, 1 - iris / diag);
            ctx.beginPath();
            ctx.arc(cx, cy, iris, 0, Math.PI * 2);
            // 번짐(shadowBlur) 대신 넓고 옅은 선 + 얇고 밝은 선 두 겹
            ctx.strokeStyle = accent;
            ctx.globalAlpha = ringA * 0.35;
            ctx.lineWidth = 22;
            ctx.stroke();
            ctx.strokeStyle = "#cfe3ff";
            ctx.globalAlpha = ringA;
            ctx.lineWidth = 5;
            ctx.stroke();
            ctx.globalAlpha = 1;
        }
        ctx.globalCompositeOperation = "source-over";
        return iris < diag;
    };
};

/** 내가 찻잔이라니!: 화면에 찬 커피가 거품 띠와 함께 아래로 빠진다 */
const drain: Factory = (w, h) => {
    const bubbles = Array.from({ length: 40 }, () => ({ x: rand(0, w), y: rand(0, h), r: rand(2, 6) }));
    return (ctx, _w, _h, t) => {
        const level = -30 + easeInOut(clamp01((t - 0.15) / 1.25)) * (h + 90);
        const wave = (x: number) => level + Math.sin(x * 0.018 + t * 7) * 12 + Math.sin(x * 0.047 - t * 5) * 5;
        // 커피
        ctx.beginPath();
        ctx.moveTo(0, h);
        for (let x = 0; x <= w; x += 12) ctx.lineTo(x, wave(x));
        ctx.lineTo(w, h);
        ctx.closePath();
        const g = ctx.createLinearGradient(0, level, 0, h);
        g.addColorStop(0, "#6b4128");
        g.addColorStop(0.15, "#3d2416");
        g.addColorStop(1, "#1f120a");
        ctx.fillStyle = g;
        ctx.fill();
        // 크레마 거품 띠
        ctx.strokeStyle = "#e9cf9f";
        ctx.lineWidth = 7;
        ctx.globalAlpha = 0.9;
        ctx.beginPath();
        for (let x = 0; x <= w; x += 12) (x === 0 ? ctx.moveTo : ctx.lineTo).call(ctx, x, wave(x) + 2);
        ctx.stroke();
        ctx.globalAlpha = 1;
        // 거품 방울
        ctx.fillStyle = "rgba(233, 207, 159, 0.35)";
        for (const b of bubbles) {
            if (b.y > wave(b.x) + 10) {
                ctx.beginPath();
                ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
                ctx.fill();
            }
        }
        return level < h + 40;
    };
};

/** Luminous: 어둠 속 가운데에서 빛살과 함께 빛이 퍼진다 */
const light: Factory = (w, h, accent) => {
    const cx = w * 0.3, cy = h * 0.42, diag = Math.hypot(w, h);
    const rays = Array.from({ length: 14 }, (_, i) => ({ a: (i / 14) * Math.PI * 2 + rand(-0.1, 0.1), wdt: rand(0.03, 0.08) }));
    return (ctx, _w, _h, t) => {
        const r = easeInOut(clamp01((t - 0.2) / 1.3)) * diag * 1.2;
        ctx.fillStyle = "#03070c";
        ctx.fillRect(0, 0, w, h);
        // 빛이 닿은 곳은 걷힌다
        ctx.globalCompositeOperation = "destination-out";
        const g = ctx.createRadialGradient(cx, cy, r * 0.35, cx, cy, r + 1);
        g.addColorStop(0, "rgba(0,0,0,1)");
        g.addColorStop(1, "rgba(0,0,0,0)");
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, w, h);
        // 빛살과 광원
        ctx.globalCompositeOperation = "lighter";
        const fade = Math.max(0, 1 - Math.max(0, t - 0.7) / 0.6);
        const glow = Math.min(1, t / 0.25) * fade;
        ctx.globalAlpha = 0.11 * glow;
        ctx.fillStyle = accent;
        ctx.beginPath();
        for (const ray of rays) {
            const a = ray.a + t * 0.25;
            ctx.moveTo(cx, cy);
            ctx.lineTo(cx + Math.cos(a - ray.wdt) * diag, cy + Math.sin(a - ray.wdt) * diag);
            ctx.lineTo(cx + Math.cos(a + ray.wdt) * diag, cy + Math.sin(a + ray.wdt) * diag);
            ctx.closePath();
        }
        ctx.fill();
        const core = ctx.createRadialGradient(cx, cy, 0, cx, cy, 90 + r * 0.12);
        core.addColorStop(0, "rgba(255,255,255,0.9)");
        core.addColorStop(0.3, accent);
        core.addColorStop(1, "transparent");
        ctx.globalAlpha = glow;
        ctx.fillStyle = core;
        ctx.beginPath();
        ctx.arc(cx, cy, 90 + r * 0.12, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
        ctx.globalCompositeOperation = "source-over";
        return t < 1.35;
    };
};

/** 마인크래프트: 흙·돌 블록에 금이 가고 부서져 떨어진다 */
const blocks: Factory = (w, h) => {
    const S = 56;
    const cols = Math.ceil(w / S), rows = Math.ceil(h / S);
    const palettes = [
        ["#79553a", "#6c4a32", "#8b6446", "#5e3f2a"], // 흙
        ["#7d7d7d", "#6e6e6e", "#8a8a8a", "#5f5f5f"], // 돌
    ];
    // 블록 텍스처 두 장을 미리 그린다 (8x8 픽셀)
    const tex = palettes.map((pal) => {
        const c = document.createElement("canvas");
        c.width = c.height = 8;
        const x = c.getContext("2d")!;
        for (let i = 0; i < 64; i++) {
            x.fillStyle = pal[Math.floor(Math.random() * pal.length)];
            x.fillRect(i % 8, Math.floor(i / 8), 1, 1);
        }
        return c;
    });
    const list: { x: number; y: number; tex: HTMLCanvasElement; delay: number; vx: number }[] = [];
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
            list.push({ x: c * S, y: r * S, tex: tex[(r * 7 + c * 3) % 5 === 0 ? 1 : Math.random() < 0.35 ? 1 : 0], delay: 0.08 + (r / rows) * 0.5 + rand(0, 0.45), vx: rand(-40, 40) });
    return (ctx, _w, _h, t) => {
        ctx.imageSmoothingEnabled = false;
        let alive = false;
        for (const b of list) {
            const p = clamp01((t - b.delay) / 0.5);
            if (p >= 1) continue;
            alive = true;
            if (p < 0.35) {
                ctx.globalAlpha = 1;
                ctx.drawImage(b.tex, b.x, b.y, S, S);
                // 금 가는 단계
                const crack = Math.floor((p / 0.35) * 4);
                ctx.fillStyle = "rgba(0,0,0,0.55)";
                for (let i = 0; i < crack * 3; i++) ctx.fillRect(b.x + ((i * 23) % S), b.y + ((i * 37) % S), 7, 7);
            } else {
                const q = (p - 0.35) / 0.65;
                const s = S * (1 - q * 0.5);
                ctx.globalAlpha = 1 - q;
                ctx.drawImage(b.tex, b.x + (S - s) / 2 + b.vx * q, b.y + (S - s) / 2 + q * q * 160, s, s);
            }
        }
        ctx.globalAlpha = 1;
        return alive;
    };
};

/** 기본: 강조색 픽셀이 대각선 물결로 사라진다 */
const pixels: Factory = (w, h, accent) => {
    const S = 34;
    const cols = Math.ceil(w / S), rows = Math.ceil(h / S);
    const list: { x: number; y: number; delay: number }[] = [];
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++) list.push({ x: c * S, y: r * S, delay: 0.08 + ((c + r) / (cols + rows)) * 0.85 + rand(0, 0.12) });
    return (ctx, _w, _h, t) => {
        let alive = false;
        for (const k of list) {
            const p = clamp01((t - k.delay) / 0.3);
            if (p >= 1) continue;
            alive = true;
            const s = S * (1 - easeIn(p));
            ctx.fillStyle = p > 0.05 ? accent : "#0c0c0c";
            ctx.globalAlpha = p > 0.05 ? 0.85 : 1;
            ctx.fillRect(k.x + (S - s) / 2, k.y + (S - s) / 2, s + 0.5, s + 0.5);
        }
        ctx.globalAlpha = 1;
        return alive;
    };
};

/**
 * 구해줘 홈즈: 게임의 점프 궤적처럼 점선 포물선이 그려지고,
 * 화면을 덮은 피자 상자들이 그 방향으로 던져져 중력에 떨어진다.
 */
const toss: Factory = (w, h, accent) => {
    const S = Math.max(90, Math.round(Math.min(w, h) / 6));
    const cols = Math.ceil(w / S), rows = Math.ceil(h / S);
    const G = 2600;
    const T0 = 0.42; // 던지기 시작
    const boxes: { x: number; y: number; vx: number; vy: number; spin: number; delay: number; shade: number }[] = [];
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
            boxes.push({
                x: c * S,
                y: r * S,
                vx: rand(250, 720),
                vy: -rand(650, 1150),
                spin: rand(-7, 7),
                delay: T0 + (c / cols) * 0.32 + ((rows - r) / rows) * 0.1 + rand(0, 0.06),
                shade: rand(-12, 12),
            });
    // 궤적 점: 왼쪽 아래에서 오른쪽 위로 (게임처럼 점이 점점 작아진다)
    const dots = Array.from({ length: 15 }, (_, i) => {
        const k = (i + 1) / 15;
        return { x: w * (0.12 + 0.62 * k), y: h * 0.82 - (h * 0.95 * k - h * 0.42 * k * k), s: 24 - i * 1.1 };
    });
    const drawBox = (ctx: CanvasRenderingContext2D, shade: number) => {
        const half = S / 2 - 3;
        ctx.fillStyle = `hsl(32, 48%, ${44 + shade * 0.3}%)`;
        ctx.fillRect(-half, -half, half * 2, half * 2);
        ctx.fillStyle = "rgba(0,0,0,0.18)";
        ctx.fillRect(-half, half * 0.55, half * 2, half * 0.45); // 옆면 그림자
        ctx.strokeStyle = "#5a3a1c";
        ctx.lineWidth = 3;
        ctx.strokeRect(-half, -half, half * 2, half * 2);
        ctx.fillStyle = "#d8402f"; // 가게 스티커
        ctx.beginPath();
        ctx.arc(0, -half * 0.15, half * 0.32, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#ffe2a8";
        ctx.fillRect(-half * 0.5, half * 0.3, half, 4);
    };
    return (ctx, _w, _h, t) => {
        let alive = false;
        // 바닥: 아직 던져지지 않은 상자
        for (const b of boxes) {
            const dt = t - b.delay;
            let x = b.x + S / 2, y = b.y + S / 2, rot = 0;
            if (dt > 0) {
                x += b.vx * dt;
                y += b.vy * dt + 0.5 * G * dt * dt;
                rot = b.spin * dt;
                if (y - S > h || x - S > w) continue;
            }
            alive = true;
            ctx.save();
            ctx.translate(x, y);
            if (rot) ctx.rotate(rot);
            drawBox(ctx, b.shade);
            ctx.restore();
        }
        // 궤적 점: 당기는 동안 하나씩 나타났다가, 던지면 사라진다
        const show = clamp01(t / 0.32);
        const fade = 1 - clamp01((t - T0) / 0.25);
        if (fade > 0) {
            alive = true;
            const n = Math.ceil(show * dots.length);
            for (let i = 0; i < n; i++) {
                const d = dots[i];
                ctx.globalAlpha = fade * 0.95;
                ctx.fillStyle = "#ffffff";
                ctx.fillRect(d.x - d.s / 2 - 2, d.y - d.s / 2 - 2, d.s + 4, d.s + 4);
                ctx.fillStyle = accent;
                ctx.fillRect(d.x - d.s / 2, d.y - d.s / 2, d.s, d.s);
            }
            ctx.globalAlpha = 1;
        }
        return alive;
    };
};

/**
 * 생존 전략!: 맵 가운데 타이머처럼 시곗바늘이 한 바퀴 돌며 덮개를 걷어 내고,
 * 시간이 다 되는 순간 붉은 섬광과 함께 화면이 흔들린다 (불꽃의 거인 등장).
 */
const clock: Factory = (w, h, accent, fx) => {
    const cx = w / 2, cy = h / 2, R = Math.hypot(w, h);
    const ring = Math.min(w, h) * 0.22;
    const T_SWEEP = 0.95, T_START = 0.18;
    let hit = false;
    return (ctx, _w, _h, t) => {
        const p = easeInOut(clamp01((t - T_START) / T_SWEEP));
        const a0 = -Math.PI / 2;
        const a = a0 + p * Math.PI * 2;
        // 남은 시간만큼의 부채꼴만 덮는다
        if (p < 1) {
            ctx.fillStyle = "#120707";
            ctx.beginPath();
            ctx.moveTo(cx, cy);
            ctx.arc(cx, cy, R, a, a0 + Math.PI * 2);
            ctx.closePath();
            ctx.fill();
            // 눈금
            ctx.strokeStyle = "rgba(255,255,255,0.35)";
            ctx.lineWidth = 3;
            ctx.beginPath();
            for (let i = 0; i < 60; i++) {
                const ta = a0 + (i / 60) * Math.PI * 2;
                if (ta < a) continue;
                const l = i % 5 === 0 ? 18 : 8;
                ctx.moveTo(cx + Math.cos(ta) * ring, cy + Math.sin(ta) * ring);
                ctx.lineTo(cx + Math.cos(ta) * (ring + l), cy + Math.sin(ta) * (ring + l));
            }
            ctx.stroke();
            // 바늘
            ctx.strokeStyle = accent;
            ctx.lineWidth = 6;
            ctx.beginPath();
            ctx.moveTo(cx, cy);
            ctx.lineTo(cx + Math.cos(a) * R, cy + Math.sin(a) * R);
            ctx.stroke();
            ctx.strokeStyle = "#fff2e0";
            ctx.lineWidth = 2;
            ctx.stroke();
            ctx.fillStyle = accent;
            ctx.beginPath();
            ctx.arc(cx, cy, 10, 0, Math.PI * 2);
            ctx.fill();
        }
        // 시간 종료: 붉은 섬광 + 흔들림
        const tEnd = T_START + T_SWEEP;
        if (!hit && t >= tEnd) {
            hit = true;
            fx.shake();
        }
        const fl = hit ? 1 - clamp01((t - tEnd) / 0.45) : 0;
        if (fl > 0) {
            ctx.globalAlpha = fl * fl * 0.7;
            const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, R * 0.6);
            g.addColorStop(0, "#ffb070");
            g.addColorStop(0.4, accent);
            g.addColorStop(1, "rgba(80,0,0,0.6)");
            ctx.fillStyle = g;
            ctx.fillRect(0, 0, w, h);
            ctx.globalAlpha = 1;
        }
        return p < 1 || fl > 0;
    };
};

/**
 * KOROSHITE: 일격에 화면이 깨지고, 파편이 회전하며 떨어진다.
 */
const shatter: Factory = (w, h, accent, fx) => {
    const ix = w * 0.56, iy = h * 0.46;
    const R = Math.hypot(Math.max(ix, w - ix), Math.max(iy, h - iy)) + 40;
    const N = 16;
    const angles = Array.from({ length: N }, (_, i) => (i / N) * Math.PI * 2 + rand(-0.12, 0.12));
    const radii = [0, 70, 190, 380, 640, R * 1.2];
    const T_HIT = 0.14;
    interface Shard { pts: [number, number][]; cx: number; cy: number; vx: number; vy: number; spin: number; delay: number; tone: number }
    const shards: Shard[] = [];
    for (let k = 0; k < radii.length - 1; k++)
        for (let i = 0; i < N; i++) {
            const a1 = angles[i], a2 = angles[(i + 1) % N] + (i === N - 1 ? Math.PI * 2 : 0);
            const r1 = radii[k] * rand(0.92, 1.08), r2 = radii[k + 1] * rand(0.92, 1.08);
            const raw: [number, number][] = [
                [Math.cos(a1) * r1, Math.sin(a1) * r1],
                [Math.cos(a1) * r2, Math.sin(a1) * r2],
                [Math.cos(a2) * r2, Math.sin(a2) * r2],
                [Math.cos(a2) * r1, Math.sin(a2) * r1],
            ];
            const mx = raw.reduce((s, p) => s + p[0], 0) / 4, my = raw.reduce((s, p) => s + p[1], 0) / 4;
            const d = Math.hypot(mx, my) || 1;
            shards.push({
                pts: raw.map(([x, y]) => [x - mx, y - my]),
                cx: ix + mx,
                cy: iy + my,
                vx: (mx / d) * rand(80, 260),
                vy: (my / d) * rand(40, 180) - rand(60, 200),
                spin: rand(-3, 3),
                delay: T_HIT + 0.12 + (k / radii.length) * 0.28 + rand(0, 0.08),
                tone: rand(0, 1),
            });
        }
    let hit = false;
    return (ctx, _w, _h, t) => {
        if (!hit && t >= T_HIT) {
            hit = true;
            fx.shake();
        }
        let alive = false;
        for (const s of shards) {
            const dt = Math.max(0, t - s.delay);
            const x = s.cx + s.vx * dt;
            const y = s.cy + s.vy * dt + 0.5 * 2200 * dt * dt;
            if (y - 300 > h) continue;
            alive = true;
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(s.spin * dt);
            ctx.beginPath();
            s.pts.forEach(([px, py], i) => (i ? ctx.lineTo(px, py) : ctx.moveTo(px, py)));
            ctx.closePath();
            ctx.fillStyle = s.tone > 0.5 ? "#101014" : "#16161c";
            ctx.fill();
            if (hit) {
                ctx.strokeStyle = dt > 0 ? "rgba(255,255,255,0.5)" : "rgba(255,255,255,0.85)";
                ctx.lineWidth = 1.5;
                ctx.stroke();
            }
            ctx.restore();
        }
        // 충격 지점 섬광
        if (hit) {
            const fl = 1 - clamp01((t - T_HIT) / 0.25);
            if (fl > 0) {
                ctx.globalCompositeOperation = "lighter";
                ctx.globalAlpha = fl;
                ctx.fillStyle = accent;
                ctx.beginPath();
                ctx.arc(ix, iy, 30 + (1 - fl) * 120, 0, Math.PI * 2);
                ctx.fill();
                ctx.fillStyle = "#ffffff";
                ctx.beginPath();
                ctx.arc(ix, iy, 14 + (1 - fl) * 40, 0, Math.PI * 2);
                ctx.fill();
                ctx.globalAlpha = 1;
                ctx.globalCompositeOperation = "source-over";
            }
        }
        return alive;
    };
};

/** Albedo: 미지의 행성을 훑는 빛줄기가 위에서 아래로 지나가며 화면을 밝힌다 */
const scan: Factory = (w, h, accent) => {
    return (ctx, _w, _h, t) => {
        const y = -60 + easeInOut(clamp01((t - 0.12) / 1.0)) * (h + 160);
        // 아직 훑지 않은 아래쪽 덮개 + 격자
        ctx.fillStyle = "#050a14";
        ctx.fillRect(0, y, w, h - y);
        ctx.strokeStyle = "rgba(120,200,255,0.08)";
        ctx.lineWidth = 1;
        ctx.beginPath();
        for (let gx = 0; gx < w; gx += 48) {
            ctx.moveTo(gx, Math.max(0, y));
            ctx.lineTo(gx, h);
        }
        for (let gy = Math.ceil(y / 48) * 48; gy < h; gy += 48) {
            ctx.moveTo(0, gy);
            ctx.lineTo(w, gy);
        }
        ctx.stroke();
        // 빛줄기
        ctx.globalCompositeOperation = "lighter";
        const g = ctx.createLinearGradient(0, y - 140, 0, y + 6);
        g.addColorStop(0, "rgba(0,0,0,0)");
        g.addColorStop(0.85, accent);
        g.addColorStop(1, "#ffffff");
        ctx.globalAlpha = 0.55;
        ctx.fillStyle = g;
        ctx.fillRect(0, y - 140, w, 146);
        ctx.globalAlpha = 1;
        ctx.fillStyle = "#ffffff";
        ctx.fillRect(0, y - 2, w, 3);
        ctx.globalCompositeOperation = "source-over";
        return y < h + 100;
    };
};

/**
 * 버튼을 눌렀더니…: 가운데 빨간 버튼이 '딸깍' 눌리고,
 * 마법진이 돌며 퍼져 판타지 세계로 넘어간다.
 */
const portal: Factory = (w, h, accent, fx) => {
    const cx = w / 2, cy = h / 2, diag = Math.hypot(w, h);
    const T_PRESS = 0.32;
    let pressed = false;
    return (ctx, _w, _h, t) => {
        const iris = easeIn(clamp01((t - T_PRESS - 0.08) / 0.8)) * diag * 0.62;
        ctx.fillStyle = "#0c0716";
        ctx.fillRect(0, 0, w, h);
        if (!pressed && t >= T_PRESS) {
            pressed = true;
            fx.shake();
        }
        // 버튼
        if (iris < 40) {
            const down = t < 0.2 ? 0 : Math.min(1, (t - 0.2) / (T_PRESS - 0.2));
            ctx.fillStyle = "#4a1018";
            ctx.beginPath();
            ctx.ellipse(cx, cy + 16, 62, 24, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = "#e23a3a";
            ctx.beginPath();
            ctx.ellipse(cx, cy + 4 + down * 10, 54, 20, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = "#ff8080";
            ctx.beginPath();
            ctx.ellipse(cx - 12, cy - 2 + down * 10, 18, 6, 0, 0, Math.PI * 2);
            ctx.fill();
        }
        if (iris > 0) {
            // 구멍
            ctx.globalCompositeOperation = "destination-out";
            ctx.beginPath();
            ctx.arc(cx, cy, iris, 0, Math.PI * 2);
            ctx.fill();
            ctx.globalCompositeOperation = "source-over";
            // 마법진 테두리: 두 겹 원 + 도는 룬 눈금
            const rot = t * 2.2;
            ctx.strokeStyle = accent;
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.arc(cx, cy, iris, 0, Math.PI * 2);
            ctx.stroke();
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.arc(cx, cy, iris + 18, 0, Math.PI * 2);
            ctx.stroke();
            ctx.fillStyle = accent;
            for (let i = 0; i < 24; i++) {
                const a = rot + (i / 24) * Math.PI * 2;
                ctx.save();
                ctx.translate(cx + Math.cos(a) * (iris + 9), cy + Math.sin(a) * (iris + 9));
                ctx.rotate(a);
                ctx.fillRect(-2, -5, 4, i % 3 === 0 ? 10 : 5);
                ctx.restore();
            }
        }
        return iris < diag * 0.6;
    };
};

/** ECHO: 가운데에서 메아리처럼 동심원이 퍼지고, 마지막 파동이 화면을 연다 */
const ripple: Factory = (w, h, accent) => {
    const cx = w / 2, cy = h / 2, diag = Math.hypot(w, h);
    return (ctx, _w, _h, t) => {
        const r = easeIn(clamp01((t - 0.5) / 0.8)) * diag * 0.6;
        ctx.fillStyle = "#081012";
        ctx.fillRect(0, 0, w, h);
        if (r > 0) {
            ctx.globalCompositeOperation = "destination-out";
            ctx.beginPath();
            ctx.arc(cx, cy, r, 0, Math.PI * 2);
            ctx.fill();
            ctx.globalCompositeOperation = "source-over";
        }
        // 앞서 퍼지는 메아리 고리 3개
        ctx.strokeStyle = accent;
        for (let i = 0; i < 4; i++) {
            const start = i * 0.16;
            const k = clamp01((t - start) / 1.1);
            if (k <= 0 || k >= 1) continue;
            const rr = r + 20 + easeInOut(k) * diag * 0.55;
            ctx.globalAlpha = (1 - k) * 0.9;
            ctx.lineWidth = 4 - i * 0.6;
            ctx.beginPath();
            ctx.arc(cx, cy, rr, 0, Math.PI * 2);
            ctx.stroke();
        }
        ctx.globalAlpha = 1;
        return r < diag * 0.6 || t < 1.3;
    };
};

/** 범근러쉬: 가로 띠들이 속도선을 남기며 왼쪽으로 질주해 빠져나간다 */
const dash: Factory = (w, h, accent) => {
    const H = 26;
    const rows = Math.ceil(h / H);
    const list = Array.from({ length: rows }, (_, r) => ({ y: r * H, delay: 0.08 + (Math.abs(r - rows / 2) / rows) * 0.35 + rand(0, 0.12), tone: rand(0, 1) }));
    return (ctx, _w, _h, t) => {
        let alive = false;
        for (const b of list) {
            const p = easeIn(clamp01((t - b.delay) / 0.55));
            if (p >= 1) continue;
            alive = true;
            const x = -p * (w + 260);
            ctx.fillStyle = b.tone > 0.7 ? "#1c1c1c" : "#121212";
            ctx.fillRect(x, b.y, w + 2, H + 0.5);
            // 띠 끝의 속도선
            if (p > 0) {
                ctx.fillStyle = accent;
                ctx.globalAlpha = 0.9;
                ctx.fillRect(x + w, b.y + H * 0.35, 30 + p * 240, 3);
                ctx.fillStyle = "#ffffff";
                ctx.globalAlpha = 0.6;
                ctx.fillRect(x + w + 10, b.y + H * 0.7, 20 + p * 120, 2);
                ctx.globalAlpha = 1;
            }
        }
        return alive;
    };
};

/** 리듬 게임: 이퀄라이저 막대가 박자에 맞춰 튀다가 차례로 떨어진다 */
const beat: Factory = (w, h, accent) => {
    const N = Math.max(10, Math.round(w / 64));
    const bw = w / N;
    const BPM_GAP = 0.15;
    const bars = Array.from({ length: N }, (_, i) => ({ phase: rand(0, Math.PI * 2), delay: 0.5 + (((i * 7) % N) / N) * 0.45 }));
    return (ctx, _w, _h, t) => {
        let alive = false;
        const pulse = Math.max(0, 1 - ((t % BPM_GAP) / BPM_GAP) * 1.6); // 박자마다 튄다
        for (let i = 0; i < N; i++) {
            const b = bars[i];
            const p = easeIn(clamp01((t - b.delay) / 0.35));
            if (p >= 1) continue;
            alive = true;
            const wob = t < b.delay ? (0.08 + 0.1 * Math.abs(Math.sin(b.phase + t * 9))) * pulse : 0;
            const top = h * wob + p * (h + 20);
            const x = i * bw;
            ctx.fillStyle = "#0b0b12";
            ctx.fillRect(x, top, bw + 0.5, h - top + 20);
            ctx.fillStyle = accent;
            ctx.fillRect(x + 3, top, bw - 6, 6);
            ctx.globalAlpha = 0.25;
            ctx.fillRect(x + bw / 2 - 1, top + 6, 2, h);
            ctx.globalAlpha = 1;
        }
        return alive;
    };
};

/** 오염된 땅을 정화하는 게임: 탁한 타일이 모서리부터 밝게 정화되며 사라진다 */
const purify: Factory = (w, h, accent) => {
    const S = 48;
    const cols = Math.ceil(w / S), rows = Math.ceil(h / S);
    const list: { x: number; y: number; delay: number; tone: number }[] = [];
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++) {
            const d = Math.hypot(c / cols, (rows - r) / rows) / Math.SQRT2; // 왼쪽 아래부터
            list.push({ x: c * S, y: r * S, delay: 0.1 + d * 0.95 + rand(0, 0.1), tone: rand(0, 1) });
        }
    return (ctx, _w, _h, t) => {
        let alive = false;
        for (const k of list) {
            const p = clamp01((t - k.delay) / 0.38);
            if (p >= 1) continue;
            alive = true;
            if (p <= 0) {
                ctx.fillStyle = k.tone > 0.66 ? "#2b1d33" : k.tone > 0.33 ? "#24202c" : "#1d2420";
                ctx.fillRect(k.x, k.y, S + 0.5, S + 0.5);
                ctx.fillStyle = "rgba(150, 90, 190, 0.18)";
                ctx.fillRect(Math.round(k.x + 6 + k.tone * 20), k.y + 8, 10, 10);
            } else {
                // 정화되는 순간 밝게 번쩍이며 작아진다
                const s = S * (1 - easeIn(p));
                ctx.globalAlpha = 1 - p * 0.4;
                ctx.fillStyle = p < 0.1 ? "#ffffff" : accent;
                ctx.fillRect(k.x + (S - s) / 2, k.y + (S - s) / 2, s, s);
                ctx.globalAlpha = 1;
            }
        }
        return alive;
    };
};

const PIXEL_FONT = '"DungGeun", "Galmuri11", monospace';

function centerText(ctx: CanvasRenderingContext2D, text: string, x: number, y: number, size: number, fill: string, stroke = "#000") {
    ctx.font = `${Math.round(size)}px ${PIXEL_FONT}`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.lineWidth = Math.max(3, size * 0.12);
    ctx.strokeStyle = stroke;
    ctx.strokeText(text, x, y);
    ctx.fillStyle = fill;
    ctx.fillText(text, x, y);
    ctx.textAlign = "start";
    ctx.textBaseline = "alphabetic";
}

/**
 * 도장을 지켜라!: 대전 격투 게임의 라운드 시작.
 * 체력 바가 양쪽에서 들어오고(0~0.3) 'ROUND 1' → 0.52초에 'FIGHT!'와 함께 흔들림 → 덮개가 좌우로 갈라진다.
 */
const fight: Factory = (w, h, accent, fx) => {
    const T_FIGHT = 0.52;
    let hit = false;
    return (ctx, _w, _h, t) => {
        if (!hit && t >= T_FIGHT) {
            hit = true;
            fx.shake();
        }
        const open = easeIn(clamp01((t - 0.72) / 0.42));
        const off = open * (w / 2 + 40);
        ctx.fillStyle = "#1b1009";
        ctx.fillRect(-off, 0, w / 2 + 1, h);
        ctx.fillRect(w / 2 + off, 0, w / 2, h);
        if (open >= 1) return false;
        // 체력 바
        const b = easeInOut(clamp01(t / 0.3));
        const bw = w * 0.36, bh = Math.max(14, h * 0.03), by = h * 0.1;
        ctx.fillStyle = "#000";
        ctx.fillRect(w * 0.06 - (1 - b) * w * 0.5 - off - 3, by - 3, bw + 6, bh + 6);
        ctx.fillRect(w * 0.58 + (1 - b) * w * 0.5 + off - 3, by - 3, bw + 6, bh + 6);
        ctx.fillStyle = "#58d65b";
        ctx.fillRect(w * 0.06 - (1 - b) * w * 0.5 - off, by, bw, bh);
        ctx.fillRect(w * 0.58 + (1 - b) * w * 0.5 + off, by, bw, bh);
        const fade = 1 - open;
        ctx.globalAlpha = fade;
        if (t > 0.15 && t < T_FIGHT) centerText(ctx, "ROUND 1", w / 2, h * 0.45, Math.min(w, h) * 0.1, "#fff4d6");
        if (t >= T_FIGHT) {
            const pop = 1 + Math.max(0, 1 - (t - T_FIGHT) / 0.14) * 0.9;
            centerText(ctx, "FIGHT!", w / 2, h * 0.45, Math.min(w, h) * 0.16 * pop, accent);
        }
        ctx.globalAlpha = 1;
        return true;
    };
};

/**
 * 루미너스 런처: 리소스 확인 진행 바가 100%까지 차고(0~0.7), PLAY가 번쩍인 뒤(0.75)
 * 오로라 하늘 덮개가 위아래로 열린다(0.85~).
 */
const launch: Factory = (w, h, accent) => {
    // 하늘(그라디언트 + 별)은 한 번만 그려 두고, 매 프레임 위아래 반쪽을 밀어내기만 한다
    const sky = document.createElement("canvas");
    sky.width = Math.ceil(w);
    sky.height = Math.ceil(h);
    const sc = sky.getContext("2d")!;
    const g = sc.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, "#0b1030");
    g.addColorStop(0.5, "#1b1650");
    g.addColorStop(1, "#0b1030");
    sc.fillStyle = g;
    sc.fillRect(0, 0, w, h);
    sc.fillStyle = "#ffffff";
    for (let i = 0; i < 90; i++) {
        sc.globalAlpha = rand(0.4, 1);
        const s = rand(1, 2.5);
        sc.fillRect(rand(0, w), rand(0, h), s, s);
    }
    const half = Math.ceil(h / 2);
    return (ctx, _w, _h, t) => {
        const open = easeIn(clamp01((t - 0.85) / 0.5));
        const off = open * (h / 2 + 20);
        ctx.drawImage(sky, 0, 0, sky.width, half, 0, -off, w, half);
        ctx.drawImage(sky, 0, half, sky.width, sky.height - half, 0, half + off, w, sky.height - half);
        if (open >= 1) return false;
        // 오로라 띠
        ctx.globalCompositeOperation = "lighter";
        ctx.globalAlpha = 0.35;
        ctx.fillStyle = "#3fd6a0";
        // 띠를 도형 하나로 그린다 (작은 사각형 수백 개보다 훨씬 가볍다)
        ctx.beginPath();
        for (let x = 0; x <= w + 24; x += 24) {
            const y = h * 0.22 + Math.sin(x * 0.01 + t * 2) * h * 0.05 - off;
            if (x === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }
        for (let x = Math.ceil((w + 24) / 24) * 24; x >= 0; x -= 24) ctx.lineTo(x, h * 0.3 + Math.sin(x * 0.01 + t * 2) * h * 0.05 - off);
        ctx.closePath();
        ctx.fill();
        ctx.globalCompositeOperation = "source-over";
        ctx.globalAlpha = 1 - open;
        const p = clamp01(t / 0.7);
        const bw = Math.min(520, w * 0.6), bx = (w - bw) / 2, by = h / 2 - 10 + off;
        ctx.fillStyle = "rgba(0,0,0,0.6)";
        ctx.fillRect(bx - 4, by - 4, bw + 8, 28);
        ctx.fillStyle = accent;
        ctx.fillRect(bx, by, bw * easeInOut(p), 20);
        centerText(ctx, p < 1 ? `리소스 확인 중 ${Math.floor(p * 100)}%` : "PLAY", w / 2, by - 36, p < 1 ? 20 : 34 * (1 + Math.max(0, 1 - (t - 0.72) / 0.12) * 0.4), "#ffffff");
        ctx.globalAlpha = 1;
        return true;
    };
};

/** 탈귀: 깜깜한 복도를 손전등 불빛이 깜빡이며 훑고(0.1~0.8), 마지막에 불빛이 화면 가득 번진다 */
const flashlight: Factory = (w, h) => {
    return (ctx, _w, _h, t) => {
        const grow = easeIn(clamp01((t - 0.8) / 0.55));
        const r = Math.min(w, h) * 0.18 + grow * Math.hypot(w, h);
        const p = easeInOut(clamp01((t - 0.1) / 0.7));
        const cx = w * (0.15 + 0.6 * p), cy = h * (0.55 + Math.sin(p * Math.PI * 2) * 0.12);
        // 손전등이 켜지기 전과 깜빡일 때는 빛이 없다
        const on = t > 0.08 && !(t > 0.3 && t < 0.34) && !(t > 0.46 && t < 0.49);
        ctx.fillStyle = "#020203";
        ctx.fillRect(0, 0, w, h);
        if (on) {
            ctx.globalCompositeOperation = "destination-out";
            const g = ctx.createRadialGradient(cx, cy, r * 0.25, cx, cy, r);
            g.addColorStop(0, "rgba(0,0,0,1)");
            g.addColorStop(1, "rgba(0,0,0,0)");
            ctx.fillStyle = g;
            ctx.fillRect(0, 0, w, h);
            ctx.globalCompositeOperation = "lighter";
            ctx.globalAlpha = 0.18 * (1 - grow);
            const g2 = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
            g2.addColorStop(0, "#fff6d0");
            g2.addColorStop(1, "rgba(0,0,0,0)");
            ctx.fillStyle = g2;
            ctx.fillRect(0, 0, w, h);
            ctx.globalAlpha = 1;
            ctx.globalCompositeOperation = "source-over";
        }
        return grow < 1;
    };
};

/** UnityUtils: 모듈 카드가 차례로 '가져오기' 체크되며 작아져 사라진다 */
const modules: Factory = (w, h, accent) => {
    const names = ["HealthObject", "Cooldown", "CamEffector", "StatController", "SoundManager", "Singleton", "RangeController", "Projectile2D", "UIBasePanel", "IndicatorManager", "Kits", "LoadingController"];
    const cols = w > 900 ? 4 : 3;
    const rows = Math.ceil(names.length / cols);
    const cw = w / cols, ch = h / rows;
    return (ctx, _w, _h, t) => {
        let alive = false;
        names.forEach((name, i) => {
            const d = 0.1 + i * 0.07;
            const p = clamp01((t - d - 0.12) / 0.3);
            if (p >= 1) return;
            alive = true;
            const c = i % cols, r = Math.floor(i / cols);
            const s = 1 - easeIn(p);
            const x = c * cw + (cw * (1 - s)) / 2, y = r * ch + (ch * (1 - s)) / 2;
            ctx.fillStyle = "#2b2b2b";
            ctx.fillRect(x, y, cw * s + 1, ch * s + 1);
            if (s > 0.4) {
                ctx.strokeStyle = "#191919";
                ctx.lineWidth = 2;
                ctx.strokeRect(x + 6, y + 6, cw * s - 12, ch * s - 12);
                ctx.fillStyle = "#3c3c3c";
                ctx.fillRect(x + 6, y + 6, cw * s - 12, 26);
                ctx.font = `14px monospace`;
                ctx.fillStyle = "#d6d6d6";
                ctx.fillText(name + ".cs", x + 16, y + 24);
                if (t > d) {
                    ctx.fillStyle = accent;
                    ctx.fillRect(x + cw * s - 34, y + 12, 14, 14);
                    ctx.fillStyle = "#1b1b1b";
                    ctx.fillText("✓", x + cw * s - 33, y + 24);
                }
            }
        });
        return alive;
    };
};

/** ChikChat: 말풍선이 번갈아 쌓이고(0~0.6) 대화창 전체가 위로 스크롤되며 빠진다 */
const chat: Factory = (w, h, accent) => {
    const msgs = Array.from({ length: 7 }, (_, i) => ({ right: i % 2 === 1, len: rand(0.18, 0.4), at: 0.05 + i * 0.08 }));
    return (ctx, _w, _h, t) => {
        const up = easeIn(clamp01((t - 0.68) / 0.5)) * (h + 40);
        ctx.fillStyle = "#eef0fb";
        ctx.fillRect(0, -up, w, h);
        ctx.fillStyle = "#4b55c8";
        ctx.fillRect(0, -up, Math.min(64, w * 0.06), h);
        const bh = Math.max(34, h * 0.07);
        msgs.forEach((m, i) => {
            if (t < m.at) return;
            const pop = Math.min(1, (t - m.at) / 0.08);
            const bw = w * m.len * pop;
            const y = h * 0.1 + i * (bh + 14) - up;
            const x = m.right ? w * 0.92 - bw : w * 0.12;
            ctx.fillStyle = m.right ? accent : "#ffffff";
            ctx.fillRect(x, y, bw, bh);
            ctx.fillStyle = m.right ? "rgba(255,255,255,0.7)" : "#c8cbe0";
            ctx.fillRect(x + 12, y + bh / 2 - 3, Math.max(0, bw - 24) * 0.8, 6);
        });
        return up < h + 40;
    };
};

/** 고아의 공장: 컨베이어 벨트 줄마다 상자가 실려 번갈아 반대 방향으로 빠져나간다 */
const conveyor: Factory = (w, h) => {
    const H = Math.max(60, Math.round(h / 8));
    const rows = Math.ceil(h / H);
    const list = Array.from({ length: rows }, (_, r) => ({ dir: r % 2 ? 1 : -1, delay: 0.25 + r * 0.06 + rand(0, 0.05) }));
    return (ctx, _w, _h, t) => {
        let alive = false;
        list.forEach((row, r) => {
            const p = easeIn(clamp01((t - row.delay) / 0.6));
            if (p >= 1) return;
            alive = true;
            const off = row.dir * p * (w + 80);
            const y = r * H;
            ctx.fillStyle = "#3a3a40";
            ctx.fillRect(off, y, w, H + 1);
            ctx.fillStyle = "#2a2a2e";
            const shift = ((t * 160 * row.dir) % 40 + 40) % 40;
            for (let x = -40; x < w + 40; x += 40) ctx.fillRect(off + x + shift, y + 6, 6, H - 12);
            ctx.fillStyle = "#55555c";
            ctx.fillRect(off, y, w, 4);
            for (let x = 30; x < w; x += 170) {
                const bx = off + x + ((r * 53) % 90), bs = H * 0.62;
                ctx.fillStyle = "#c08a4e";
                ctx.fillRect(bx, y + (H - bs) / 2, bs, bs);
                ctx.fillStyle = "#8e6234";
                ctx.fillRect(bx + bs / 2 - 3, y + (H - bs) / 2, 6, bs);
            }
        });
        return alive;
    };
};

/** Video Particle: 영상 한 장면이 점 입자로 바뀌어 바깥으로 흩어진다 */
const particle: Factory = (w, h, accent) => {
    // 화면이 넓어도 점 개수가 3,000개 안팎이 되도록 점 크기를 키운다
    const S = Math.max(16, Math.round(Math.sqrt((w * h) / 3000)));
    const cols = Math.ceil(w / S), rows = Math.ceil(h / S);
    const cx = w / 2, cy = h / 2, maxD = Math.hypot(cx, cy);
    const dots = [] as { x: number; y: number; vx: number; vy: number; delay: number; c: string }[];
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++) {
            const x = c * S + S / 2, y = r * S + S / 2;
            const d = Math.hypot(x - cx, y - cy) / maxD;
            const ang = Math.atan2(y - cy, x - cx) + rand(-0.4, 0.4);
            const sp = rand(160, 420);
            // 가짜 영상 프레임: 가로 줄무늬 + 강조색 원
            const band = Math.floor((y / h) * 6) % 2;
            const inCircle = Math.hypot(x - cx, (y - cy) * 1.2) < Math.min(w, h) * 0.22;
            dots.push({ x, y, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp - 60, delay: 0.12 + (1 - d) * 0.45 + rand(0, 0.1), c: inCircle ? accent : band ? "#1d2a44" : "#273857" });
        }
    return (ctx, _w, _h, t) => {
        let alive = false;
        for (const d of dots) {
            const dt = t - d.delay;
            if (dt <= 0) {
                alive = true;
                ctx.globalAlpha = 1;
                ctx.fillStyle = d.c;
                ctx.fillRect(d.x - S / 2, d.y - S / 2, S + 0.5, S + 0.5);
                continue;
            }
            if (dt > 0.6) continue;
            alive = true;
            const k = dt / 0.6;
            ctx.globalAlpha = 1 - k;
            ctx.fillStyle = d.c;
            const s = S * (0.5 - k * 0.3);
            ctx.fillRect(d.x + d.vx * dt - s / 2, d.y + d.vy * dt - s / 2, s, s);
        }
        ctx.globalAlpha = 1;
        return alive;
    };
};

/** myPage: DOS 콘솔에 명령이 타이핑되고(0~0.55), 엔터 뒤 브라운관이 꺼지듯 화면이 한 줄로 접혀 사라진다 */
const terminal: Factory = (w, h, accent) => {
    const cmd = "C:\\DEV\\ME> start portfolio.exe";
    return (ctx, _w, _h, t) => {
        const fold = clamp01((t - 0.7) / 0.35);
        if (fold < 0.6) {
            const sy = 1 - easeIn(fold / 0.6) * 0.995;
            const hh = h * sy;
            ctx.fillStyle = "#050805";
            ctx.fillRect(0, (h - hh) / 2, w, hh);
            if (fold === 0) {
                ctx.font = `${Math.max(16, Math.min(28, w / 40))}px monospace`;
                ctx.fillStyle = accent;
                ctx.fillText("DOS.CONSOLE :: PROFILE", w * 0.08, h * 0.35);
                const n = Math.floor(clamp01(t / 0.55) * cmd.length);
                const cur = Math.floor(t * 6) % 2 ? "_" : " ";
                ctx.fillStyle = "#d8ffd8";
                ctx.fillText(cmd.slice(0, n) + cur, w * 0.08, h * 0.45);
                if (t > 0.6) ctx.fillText("OK.", w * 0.08, h * 0.53);
            } else {
                ctx.fillStyle = "#e8ffe8";
                ctx.globalAlpha = 0.5 * fold;
                ctx.fillRect(0, h / 2 - hh / 2, w, hh);
                ctx.globalAlpha = 1;
            }
            return true;
        }
        // 가운데 점으로 줄어든 빛
        const k = (fold - 0.6) / 0.4;
        if (k >= 1) return false;
        ctx.fillStyle = "#ffffff";
        const lw = w * (1 - k);
        ctx.fillRect((w - lw) / 2, h / 2 - 1, lw, 3);
        return true;
    };
};

/** mcCmd: 채팅창에 명령어가 타이핑되고(0~0.5) 실행 메시지 뒤 계단 모양 초록 줄이 아래부터 덮개를 지운다 */
const command: Factory = (w, h) => {
    const cmd = "/execute as @a run reveal page";
    const S = 24;
    const cols = Math.ceil(w / S);
    const steps = Array.from({ length: cols }, () => rand(0, 0.18));
    return (ctx, _w, _h, t) => {
        const wipe = clamp01((t - 0.6) / 0.55);
        ctx.fillStyle = "#0e0e0e";
        let alive = false;
        for (let c = 0; c < cols; c++) {
            const p = clamp01(wipe * 1.2 - steps[c]);
            const top = h * (1 - easeIn(p));
            const ty = Math.floor(top / S) * S;
            if (ty > 0) {
                alive = true;
                ctx.fillRect(c * S, 0, S + 0.5, ty);
                if (p > 0) {
                    ctx.fillStyle = "#55ff55";
                    ctx.fillRect(c * S, ty - 4, S + 0.5, 4);
                    ctx.fillStyle = "#0e0e0e";
                }
            }
        }
        if (wipe < 0.3) {
            ctx.globalAlpha = 1 - wipe / 0.3;
            const by = h - 70;
            ctx.fillStyle = "rgba(0,0,0,0.6)";
            ctx.fillRect(20, by, w - 40, 32);
            ctx.font = "18px monospace";
            ctx.fillStyle = "#ffffff";
            const n = Math.floor(clamp01(t / 0.5) * cmd.length);
            ctx.fillText(cmd.slice(0, n) + (Math.floor(t * 6) % 2 ? "_" : ""), 32, by + 22);
            if (t > 0.5) {
                ctx.fillStyle = "#55ff55";
                ctx.fillText("명령을 실행했습니다.", 32, by - 16);
            }
            ctx.globalAlpha = 1;
        }
        return alive || wipe < 1;
    };
};

/** Hunger of War: '마을 식량' 바가 바닥나고(0~0.4) 원형 마을 울타리가 가운데부터 넓어지며 열린다 */
const village: Factory = (w, h, accent) => {
    const cx = w / 2, cy = h / 2, R = Math.hypot(w, h) * 0.55;
    return (ctx, _w, _h, t) => {
        const r = easeIn(clamp01((t - 0.35) / 0.85)) * R;
        ctx.fillStyle = "#2f3a24";
        ctx.fillRect(0, 0, w, h);
        if (r > 0) {
            ctx.globalCompositeOperation = "destination-out";
            ctx.beginPath();
            ctx.arc(cx, cy, r, 0, Math.PI * 2);
            ctx.fill();
            ctx.globalCompositeOperation = "source-over";
            // 울타리 말뚝
            const n = Math.max(24, Math.round(r / 9));
            ctx.fillStyle = "#8a6440";
            for (let i = 0; i < n; i++) {
                const a = (i / n) * Math.PI * 2;
                ctx.save();
                ctx.translate(cx + Math.cos(a) * r, cy + Math.sin(a) * r);
                ctx.rotate(a);
                ctx.fillRect(-5, -4, 14, 8);
                ctx.restore();
            }
            ctx.strokeStyle = "#5e4127";
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.arc(cx, cy, r + 4, 0, Math.PI * 2);
            ctx.stroke();
        }
        // 식량 바
        const food = 1 - clamp01(t / 0.4);
        const fa = 1 - clamp01((t - 0.4) / 0.3);
        if (fa > 0) {
            ctx.globalAlpha = fa;
            const bw = Math.min(360, w * 0.5), bx = (w - bw) / 2, by = h * 0.12;
            ctx.fillStyle = "#000";
            ctx.fillRect(bx - 3, by - 3, bw + 6, 22);
            ctx.fillStyle = food > 0.3 ? accent : "#e2493a";
            ctx.fillRect(bx, by, bw * food, 16);
            centerText(ctx, `마을 식량 ${Math.round(food * 100)}%`, w / 2, by - 18, 18, "#ffffff");
            ctx.globalAlpha = 1;
        }
        return r < R;
    };
};

/** 마인크래프트에서 만나는 제주바다: 바닷물이 거품 띠와 함께 빠져나가며 조간대가 드러난다 */
const tide: Factory = (w, h) => {
    const bubbles = Array.from({ length: 50 }, () => ({ x: rand(0, w), y: rand(0, h), r: rand(2, 6) }));
    return (ctx, _w, _h, t) => {
        const edge = -40 + (1 - easeInOut(clamp01((t - 0.1) / 1.1))) * (w + 120);
        const wave = (y: number) => edge + Math.sin(y * 0.02 + t * 6) * 18 + Math.sin(y * 0.05 - t * 4) * 8;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        for (let y = 0; y <= h; y += 12) ctx.lineTo(wave(y), y);
        ctx.lineTo(0, h);
        ctx.closePath();
        const g = ctx.createLinearGradient(0, 0, w, 0);
        g.addColorStop(0, "#0b3d63");
        g.addColorStop(1, "#1f7fa8");
        ctx.fillStyle = g;
        ctx.fill();
        ctx.strokeStyle = "#e9fbff";
        ctx.lineWidth = 6;
        ctx.globalAlpha = 0.85;
        ctx.beginPath();
        for (let y = 0; y <= h; y += 12) (y === 0 ? ctx.moveTo : ctx.lineTo).call(ctx, wave(y), y);
        ctx.stroke();
        ctx.globalAlpha = 0.5;
        ctx.fillStyle = "#d6f4ff";
        for (const b of bubbles) {
            if (b.x < wave(b.y) - 10) {
                ctx.beginPath();
                ctx.arc(b.x, b.y - ((t * 60) % 40), b.r, 0, Math.PI * 2);
                ctx.fill();
            }
        }
        ctx.globalAlpha = 1;
        return edge > -30;
    };
};

/** 로프앤파이터: 밧줄에 매달린 현수막 다섯 장이 차례로 끊어져(0.3~) 흔들리며 떨어진다 */
const rope: Factory = (w, h, accent, fx) => {
    const N = 5;
    const pw = w / N;
    const panels = Array.from({ length: N }, (_, i) => ({ cut: 0.3 + i * 0.1 + rand(0, 0.04), spin: rand(-1.4, 1.4), vx: rand(-60, 60) }));
    let hit = false;
    return (ctx, _w, _h, t) => {
        if (!hit && t >= 0.3) {
            hit = true;
            fx.shake();
        }
        let alive = false;
        panels.forEach((p, i) => {
            const dt = Math.max(0, t - p.cut);
            const y = 0.5 * 2600 * dt * dt;
            if (y > h + 200) return;
            alive = true;
            const x = i * pw;
            ctx.save();
            ctx.translate(x + pw / 2 + p.vx * dt, h / 2 + 20 + y);
            ctx.rotate(p.spin * dt * dt * 3 + (dt === 0 ? Math.sin(t * 6 + i) * 0.015 : 0));
            ctx.fillStyle = i % 2 ? "#2a1616" : "#331b1b";
            ctx.fillRect(-pw / 2, -h / 2 + 20, pw + 1, h);
            ctx.fillStyle = accent;
            ctx.fillRect(-pw / 2, -h / 2 + 20, pw + 1, 8);
            ctx.restore();
            // 밧줄 (끊어지기 전까지)
            if (dt === 0) {
                ctx.strokeStyle = "#c9a26a";
                ctx.lineWidth = 4;
                ctx.beginPath();
                ctx.moveTo(x + pw / 2, 0);
                ctx.lineTo(x + pw / 2, 26);
                ctx.stroke();
            }
        });
        return alive;
    };
};

/** 스릴있는 점프게임: 캐릭터가 위에서 떨어져 내리찍는 순간(0.38) 충격파와 함께 도시 덮개가 세로로 갈라져 무너진다 */
const stomp: Factory = (w, h, accent, fx) => {
    const T_HIT = 0.38;
    const N = 14;
    const sw = w / N;
    const slices = Array.from({ length: N }, (_, i) => ({ delay: T_HIT + 0.05 + (Math.abs(i - (N - 1) / 2) / N) * 0.35, spin: rand(-0.6, 0.6) }));
    const sky = Array.from({ length: N * 2 }, () => rand(0.15, 0.4));
    let hit = false;
    return (ctx, _w, _h, t) => {
        if (!hit && t >= T_HIT) {
            hit = true;
            fx.shake();
        }
        let alive = false;
        slices.forEach((s, i) => {
            const dt = Math.max(0, t - s.delay);
            const y = 0.5 * 3000 * dt * dt;
            if (y > h + 50) return;
            alive = true;
            ctx.save();
            ctx.translate(i * sw + sw / 2, h / 2 + y);
            ctx.rotate(s.spin * dt);
            ctx.fillStyle = "#0e1018";
            ctx.fillRect(-sw / 2, -h / 2, sw + 1, h);
            // 빌딩 실루엣
            ctx.fillStyle = "#1c2030";
            const bh = h * sky[i * 2];
            ctx.fillRect(-sw / 2, h / 2 - bh, sw * 0.6, bh);
            ctx.fillRect(-sw / 2 + sw * 0.55, h / 2 - h * sky[i * 2 + 1], sw * 0.45, h * sky[i * 2 + 1]);
            ctx.restore();
        });
        // 떨어지는 캐릭터와 충격파
        if (t < T_HIT) {
            const y = (t / T_HIT) ** 2 * h * 0.82;
            ctx.fillStyle = accent;
            ctx.fillRect(w / 2 - 10, y - 30, 20, 30);
            ctx.fillStyle = "#ffffff";
            ctx.fillRect(w / 2 - 3, y - 70, 6, 34);
        } else {
            const k = clamp01((t - T_HIT) / 0.4);
            ctx.globalAlpha = 1 - k;
            ctx.strokeStyle = "#ffffff";
            ctx.lineWidth = 6 * (1 - k) + 1;
            ctx.beginPath();
            ctx.ellipse(w / 2, h * 0.82, 30 + k * w * 0.5, 8 + k * 60, 0, 0, Math.PI * 2);
            ctx.stroke();
            ctx.globalAlpha = 1;
        }
        return alive || t < 0.8;
    };
};

/** Block Beat: 레인마다 노트 블록이 내려와 판정선에 닿으면 그 레인이 지워지고, 마지막에 PERFECT */
const rhythm: Factory = (w, h, accent) => {
    const L = 6;
    const lw = w / L;
    const judge = h * 0.82;
    const lanes = Array.from({ length: L }, (_, i) => ({ hit: 0.3 + ((i * 3) % L) * 0.08 }));
    return (ctx, _w, _h, t) => {
        let alive = false;
        lanes.forEach((ln, i) => {
            const clear = easeIn(clamp01((t - ln.hit) / 0.3));
            if (clear >= 1) return;
            alive = true;
            const x = i * lw;
            ctx.fillStyle = i % 2 ? "#0d0d18" : "#121222";
            ctx.fillRect(x, clear * h, lw + 0.5, h);
            if (t < ln.hit) {
                // 내려오는 노트
                const ny = judge * (t / ln.hit);
                ctx.fillStyle = accent;
                ctx.fillRect(x + 8, ny - 16, lw - 16, 16);
            } else if (t < ln.hit + 0.15) {
                ctx.globalAlpha = 1 - (t - ln.hit) / 0.15;
                ctx.fillStyle = "#ffffff";
                ctx.fillRect(x, judge - 20, lw, 40);
                ctx.globalAlpha = 1;
            }
        });
        // 판정선
        if (alive) {
            ctx.fillStyle = "rgba(255,255,255,0.6)";
            ctx.fillRect(0, judge, w, 3);
        }
        if (t > 0.72 && t < 1.15) {
            ctx.globalAlpha = 1 - clamp01((t - 0.95) / 0.2);
            centerText(ctx, "PERFECT!", w / 2, h * 0.45, Math.min(w, h) * 0.11 * (1 + Math.max(0, 1 - (t - 0.72) / 0.1) * 0.5), "#ffe45c");
            ctx.globalAlpha = 1;
        }
        return alive || t < 1.15;
    };
};

/** 파머의 해피 라이프: 밭 타일에 새싹이 왼쪽부터 자라나고, 다 자란 타일이 차례로 걷힌다 */
const harvest: Factory = (w, h) => {
    const S = 56;
    const cols = Math.ceil(w / S), rows = Math.ceil(h / S);
    const tiles = [] as { x: number; y: number; delay: number }[];
    for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) tiles.push({ x: c * S, y: r * S, delay: 0.08 + (c / cols) * 0.75 + rand(0, 0.08) });
    return (ctx, _w, _h, t) => {
        let alive = false;
        for (const k of tiles) {
            const p = clamp01((t - k.delay) / 0.4);
            if (p >= 1) continue;
            alive = true;
            const shrink = clamp01((p - 0.6) / 0.4);
            const s = S * (1 - easeIn(shrink));
            const x = k.x + (S - s) / 2, y = k.y + (S - s) / 2;
            ctx.fillStyle = "#6b4a2f";
            ctx.fillRect(x, y, s + 0.5, s + 0.5);
            ctx.fillStyle = "#5a3d26";
            ctx.fillRect(x, y + s * 0.3, s, 4);
            ctx.fillRect(x, y + s * 0.65, s, 4);
            // 새싹이 자란다
            const g = clamp01(p / 0.6);
            if (g > 0 && s > 10) {
                const cx = x + s / 2, base = y + s * 0.75;
                ctx.fillStyle = "#7bd65a";
                ctx.fillRect(cx - 2, base - s * 0.45 * g, 4, s * 0.45 * g);
                if (g > 0.5) {
                    ctx.fillRect(cx - 10 * g, base - s * 0.45 * g, 9 * g, 6);
                    ctx.fillRect(cx + 2, base - s * 0.35 * g, 9 * g, 6);
                }
            }
        }
        return alive;
    };
};

/** Valorant Addon: 탄흔이 연달아 박히고(0.12~0.52), 마지막 한 발(0.7)에 덮개가 통째로 떨어져 나간다 */
const bullet: Factory = (w, h, accent, fx) => {
    const shots = [0.12, 0.22, 0.32, 0.42, 0.52].map((at) => ({ at, x: rand(w * 0.15, w * 0.85), y: rand(h * 0.2, h * 0.8), cracks: Array.from({ length: 6 }, () => [rand(0, Math.PI * 2), rand(20, 70)]) }));
    const T_LAST = 0.7;
    let hit = false;
    return (ctx, _w, _h, t) => {
        if (!hit && t >= T_LAST) {
            hit = true;
            fx.shake();
        }
        const dt = Math.max(0, t - T_LAST - 0.05);
        const y = 0.5 * 2800 * dt * dt;
        if (y > h + 100) return false;
        ctx.save();
        ctx.translate(w / 2, h / 2 + y);
        ctx.rotate(dt * dt * 1.2);
        ctx.fillStyle = "#121418";
        ctx.fillRect(-w / 2 - 2, -h / 2 - 2, w + 4, h + 4);
        for (const s of shots) {
            if (t < s.at) continue;
            const x = s.x - w / 2, yy = s.y - h / 2;
            ctx.strokeStyle = "rgba(255,255,255,0.55)";
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            for (const [a, l] of s.cracks) {
                ctx.moveTo(x, yy);
                ctx.lineTo(x + Math.cos(a) * l, yy + Math.sin(a) * l);
            }
            ctx.stroke();
            ctx.fillStyle = "#000";
            ctx.beginPath();
            ctx.arc(x, yy, 6, 0, Math.PI * 2);
            ctx.fill();
            // 총구 섬광
            const f = 1 - clamp01((t - s.at) / 0.08);
            if (f > 0) {
                ctx.globalAlpha = f;
                ctx.fillStyle = accent;
                ctx.beginPath();
                ctx.arc(x, yy, 26, 0, Math.PI * 2);
                ctx.fill();
                ctx.globalAlpha = 1;
            }
        }
        ctx.restore();
        return true;
    };
};

/** 2913SimpleDB: 테이블 행이 위부터 INSERT 표시와 함께 차례로 오른쪽으로 빠져나간다 */
const table: Factory = (w, h, accent) => {
    const RH = Math.max(40, Math.round(h / 12));
    const rows = Math.ceil(h / RH);
    const colsX = [0.04, 0.2, 0.48, 0.7];
    return (ctx, _w, _h, t) => {
        let alive = false;
        for (let r = 0; r < rows; r++) {
            const d = 0.15 + r * 0.06;
            const p = easeIn(clamp01((t - d - 0.12) / 0.35));
            if (p >= 1) continue;
            alive = true;
            const x = p * (w + 40), y = r * RH;
            ctx.fillStyle = r === 0 ? "#2b2b38" : r % 2 ? "#f7f7fb" : "#ececf4";
            ctx.fillRect(x, y, w, RH + 0.5);
            ctx.fillStyle = r === 0 ? "#ffffff" : "#444";
            ctx.font = `${Math.round(RH * 0.38)}px monospace`;
            const cells = r === 0 ? ["id", "text", "int", "bool"] : [String(r), `row_${r}`, String((r * 37) % 100), r % 2 ? "true" : "false"];
            cells.forEach((c, i) => ctx.fillText(c, x + w * colsX[i], y + RH * 0.65));
            if (t > d && r > 0) {
                ctx.fillStyle = accent;
                ctx.fillRect(x + w * 0.88, y + RH * 0.2, w * 0.09, RH * 0.6);
                ctx.fillStyle = "#1b1b1b";
                ctx.fillText("INSERT", x + w * 0.885, y + RH * 0.65);
            }
        }
        return alive;
    };
};

/** 가장자리가 부드러워 절반 해상도로 그려도 티가 나지 않는 연출 */
const SOFT = new Set<string>(["light", "warp", "drain", "scan", "flashlight", "tide"]);

const FACTORIES: Record<Exclude<RevealStyle, "burn">, Factory> = {
    slash,
    cards,
    warp,
    drain,
    light,
    blocks,
    pixels,
    toss,
    clock,
    shatter,
    scan,
    portal,
    ripple,
    dash,
    beat,
    purify,
    fight,
    launch,
    flashlight,
    modules,
    chat,
    conveyor,
    particle,
    terminal,
    command,
    village,
    tide,
    rope,
    stomp,
    rhythm,
    harvest,
    bullet,
    table,
};

function CanvasReveal({ style, accent }: { style: Exclude<RevealStyle, "burn">; accent: string }) {
    const ref = useRef<HTMLCanvasElement>(null);
    const [done, setDone] = useState(false);

    useEffect(() => {
        const canvas = ref.current;
        if (!canvas) return;
        if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) {
            setDone(true);
            return;
        }
        const ctx = canvas.getContext("2d");
        if (!ctx) return;
        // 짧은 전환 연출이라 고해상도로 그릴 필요가 없다. 가장자리가 부드러운 연출은 절반 해상도로 그린다
        const dpr = SOFT.has(style) ? 0.5 : 1;
        const w = canvas.clientWidth, h = canvas.clientHeight;
        canvas.width = Math.round(w * dpr);
        canvas.height = Math.round(h * dpr);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        // 임팩트 순간 뒤에 드러나는 페이지(배경·내용)까지 함께 흔든다
        const page = canvas.closest(".pj-page");
        const shake = () => {
            const frames = [
                { transform: "translate(0, 0)" },
                { transform: "translate(-14px, 8px)" },
                { transform: "translate(12px, -9px)" },
                { transform: "translate(-9px, 5px)" },
                { transform: "translate(6px, -4px)" },
                { transform: "translate(-3px, 2px)" },
                { transform: "translate(0, 0)" },
            ];
            page?.querySelectorAll(".pj-page-grid, .pj-hero-bg").forEach((el) => el.animate(frames, { duration: 420, easing: "ease-out" }));
        };
        const draw = FACTORIES[style](w, h, accent, { shake });
        playReveal(style);
        let raf = 0;
        const start = performance.now();
        const frame = (now: number) => {
            const t = (now - start) / 1000;
            ctx.clearRect(0, 0, w, h);
            const alive = draw(ctx, w, h, t);
            if (alive && t < 4) raf = requestAnimationFrame(frame);
            else setDone(true);
        };
        // 첫 프레임을 바로 그려서 덮개가 늦게 나타나지 않게 한다
        draw(ctx, w, h, 0);
        raf = requestAnimationFrame(frame);
        return () => cancelAnimationFrame(raf);
    }, [style, accent]);

    if (done) return null;
    return <canvas ref={ref} className="pj-reveal" aria-hidden="true" />;
}

export default function RevealFx({ style, accent }: { style: RevealStyle; accent: string }) {
    if (style === "burn") return <BurnReveal />;
    return <CanvasReveal style={style} accent={accent} />;
}
