import type { RevealStyle } from "../content";

/**
 * 등장 연출 효과음. 음원 파일 없이 그 자리에서 합성한다.
 * - 16비트 콘솔 게임 느낌: 32kHz로 샘플을 직접 계산하고(펄스파·FM 음색·피치 노이즈),
 *   마지막에 해상도를 낮추고(비트 크러시) 살짝 찌그러뜨린 뒤 짧은 에코를 건다.
 * - 타격감: 음정이 뚝 떨어지는 킥 + 짧은 노이즈 '딱' + 저음 펄스를 겹친 임팩트를 연출의 충돌 순간에 맞춘다.
 * - 기본은 꺼짐. 상단 바의 소리 버튼으로 켜면 이 브라우저에 기억한다.
 * - 브라우저 자동 재생 정책 때문에, 사용자가 페이지에서 한 번도 클릭·키 입력을 하지 않았으면 재생하지 않는다.
 *   (검색 결과에서 바로 들어온 첫 화면은 조용하고, 사이트 안에서 이동하면 소리가 난다)
 * - 각 연출의 시각은 revealFx.tsx, burnReveal.tsx 의 상수와 맞춘다.
 */

const STORAGE_KEY = "pj-sound";
const MASTER_GAIN = 0.55;
const SR = 32000; // 슈퍼패미컴 음원 칩과 같은 샘플레이트

let ctx: AudioContext | null = null;
let master: GainNode | null = null;
const listeners = new Set<(on: boolean) => void>();
let memo: boolean | null = null;

export function isSoundOn(): boolean {
    try {
        return localStorage.getItem(STORAGE_KEY) === "on";
    } catch {
        return false;
    }
}

export function setSoundOn(on: boolean) {
    try {
        localStorage.setItem(STORAGE_KEY, on ? "on" : "off");
    } catch {
        /* 저장할 수 없으면 이번 방문 동안만 */
    }
    memo = on;
    listeners.forEach((f) => f(on));
    if (!on && ctx) void ctx.suspend();
}

function soundOn() {
    if (memo === null) memo = isSoundOn();
    return memo;
}

export function onSoundChange(f: (on: boolean) => void) {
    listeners.add(f);
    return () => {
        listeners.delete(f);
    };
}

/** 사용자 입력이 있었던 페이지에서만 오디오를 연다 (없으면 null) */
function audio(): AudioContext | null {
    if (typeof window === "undefined" || !soundOn()) return null;
    const ua = (navigator as Navigator & { userActivation?: { hasBeenActive: boolean } }).userActivation;
    if (ua && !ua.hasBeenActive) return null;
    const AC = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!AC) return null;
    if (!ctx) {
        ctx = new AC();
        master = ctx.createGain();
        master.gain.value = MASTER_GAIN;
        // 큰 임팩트가 겹쳐도 찢어지지 않게
        const comp = ctx.createDynamicsCompressor();
        comp.threshold.value = -10;
        comp.ratio.value = 4;
        comp.attack.value = 0.002;
        master.connect(comp).connect(ctx.destination);
    }
    if (ctx.state === "suspended") void ctx.resume();
    return ctx;
}

/* ------------------------------------------------------------------ */
/* 샘플 합성 도구 (모든 시각은 초, 연출 시작 기준)                            */
/* ------------------------------------------------------------------ */

type Buf = Float32Array;
const TAU = Math.PI * 2;
const rand = (a: number, b: number) => a + Math.random() * (b - a);

interface Voice {
    at: number;
    dur: number;
    gain: number;
    attack?: number; // 차오르는 시간
    k?: number; // 감쇠 세기 (클수록 빨리 줄어든다)
}

interface Osc extends Voice {
    freq: number;
    to?: number; // 끝 음정
    sweep?: number; // 음정이 끝 음정에 닿는 시간 (기본: dur)
    wave?: "pulse" | "tri" | "saw" | "sine" | "fm";
    duty?: number; // 펄스 폭 (0.125 / 0.25 / 0.5)
    ratio?: number; // FM: 모듈레이터 배율
    index?: number; // FM: 변조 깊이 (밝기)
    indexDecay?: number; // FM: 밝기가 줄어드는 속도
}

interface Noise extends Voice {
    hold?: number; // 같은 값을 유지하는 샘플 수. 클수록 음이 낮고 거칠다
    holdTo?: number;
    lp?: number; // 저역 통과 (0~1, 작을수록 먹먹)
    hp?: boolean; // 고역만 남긴다
}

/**
 * 엔벨로프: 짧게 차오른 뒤 지수로 줄어든다. 샘플마다 exp를 부르지 않도록 곱셈으로 누적한다.
 * 끝 4ms는 선형으로 0까지 내려 '틱' 소리를 막는다.
 */
function makeEnv(v: Voice) {
    const a = Math.max(1, Math.round((v.attack ?? 0.002) * SR));
    const n = Math.floor(v.dur * SR);
    const k = v.k ?? 5;
    const mul = Math.exp(-k / Math.max(1, n - a));
    const fade = Math.round(0.004 * SR);
    let i = 0, dec = v.gain;
    return () => {
        let amp: number;
        if (i < a) amp = (v.gain * i) / a;
        else {
            amp = dec;
            dec *= mul;
        }
        const left = n - i;
        if (left < fade) amp *= Math.max(0, left / fade);
        i++;
        return amp;
    };
}

function osc(b: Buf, o: Osc) {
    const s0 = Math.floor(o.at * SR);
    const n = Math.min(Math.floor(o.dur * SR), b.length - s0);
    const wave = o.wave ?? "pulse";
    const duty = o.duty ?? 0.5;
    const ratio = o.ratio ?? 2;
    const index = o.index ?? 2;
    const idxMul = Math.exp(-(o.indexDecay ?? 5) / SR);
    // 음정 이동: 매 샘플 같은 비율을 곱해 sweep 동안 to 에 닿게 한다
    const sweepN = Math.max(1, Math.floor((o.sweep ?? o.dur) * SR));
    const fMul = o.to ? Math.pow(o.to / o.freq, 1 / sweepN) : 1;
    const env = makeEnv(o);
    let ph = 0, mph = 0, f = o.freq, idx = index;
    for (let i = 0; i < n; i++) {
        if (i < sweepN) f *= fMul;
        ph += f / SR;
        ph -= Math.floor(ph);
        let v: number;
        switch (wave) {
            case "pulse":
                v = ph < duty ? 1 : -1;
                break;
            case "tri":
                v = 1 - 4 * Math.abs(ph - 0.5);
                break;
            case "saw":
                v = 2 * ph - 1;
                break;
            case "fm":
                mph += (f * ratio) / SR;
                mph -= Math.floor(mph);
                v = Math.sin(TAU * ph + idx * Math.sin(TAU * mph));
                idx *= idxMul;
                break;
            default:
                v = Math.sin(TAU * ph);
        }
        b[s0 + i] += v * env();
    }
}

function noise(b: Buf, o: Noise) {
    const s0 = Math.floor(o.at * SR);
    const n = Math.min(Math.floor(o.dur * SR), b.length - s0);
    const h0 = o.hold ?? 1, h1 = o.holdTo ?? h0;
    const lp = o.lp ?? 1;
    const env = makeEnv(o);
    let val = 0, cnt = 0, y = 0;
    for (let i = 0; i < n; i++) {
        if (cnt-- <= 0) {
            val = Math.random() * 2 - 1;
            cnt = Math.max(1, Math.round(h0 + ((h1 - h0) * i) / n)) - 1;
        }
        y += lp * (val - y);
        b[s0 + i] += (o.hp ? val - y : y) * env();
    }
}

/* 자주 쓰는 소리 조합 ---------------------------------------------- */

/** 킥: 음정이 뚝 떨어지는 저음 + 앞머리 '딱' */
function kick(b: Buf, at: number, g = 1, from = 170, to = 42) {
    osc(b, { at, dur: 0.32, freq: from, to, sweep: 0.07, wave: "sine", gain: g, k: 4 });
    osc(b, { at, dur: 0.09, freq: from * 0.5, to: to * 0.5, sweep: 0.05, wave: "pulse", duty: 0.5, gain: g * 0.25, k: 4 });
    noise(b, { at, dur: 0.018, gain: g * 0.7, k: 3 });
}

/** 큰 임팩트: 킥 + 노이즈 폭발 + 저음 펄스 */
function impact(b: Buf, at: number, g = 1, from = 150) {
    kick(b, at, g, from, 34);
    noise(b, { at, dur: 0.38, hold: 1, holdTo: 5, lp: 0.55, gain: g * 0.6, k: 5 });
    osc(b, { at, dur: 0.22, freq: 92, to: 40, wave: "pulse", duty: 0.25, gain: g * 0.3, k: 3 });
}

function snare(b: Buf, at: number, g = 0.6) {
    noise(b, { at, dur: 0.15, hold: 1, gain: g, k: 6 });
    osc(b, { at, dur: 0.07, freq: 240, to: 130, wave: "tri", gain: g * 0.7, k: 4 });
}

/** 바람 가르는 소리. rise=true면 음이 올라가며 다가온다 */
function swish(b: Buf, at: number, dur: number, g = 0.4, rise = false) {
    noise(b, { at, dur, hold: rise ? 7 : 1, holdTo: rise ? 1 : 6, lp: 0.6, gain: g, attack: dur * (rise ? 0.75 : 0.25), k: 3 });
}

/** FM 종소리 (금속성, 메가드라이브 톤) */
function bell(b: Buf, at: number, freq: number, dur = 0.6, g = 0.2) {
    osc(b, { at, dur, freq, wave: "fm", ratio: 3.5, index: 2.6, indexDecay: 7, gain: g, k: 4 });
}

/** FM 브라스 화음 한 음 */
function brass(b: Buf, at: number, freq: number, dur = 0.8, g = 0.15, attack = 0.03) {
    osc(b, { at, dur, freq, wave: "fm", ratio: 1, index: 3.2, indexDecay: 3, gain: g, attack, k: 3 });
}

function blip(b: Buf, at: number, freq: number, dur = 0.07, g = 0.22, duty = 0.25) {
    osc(b, { at, dur, freq, wave: "pulse", duty, gain: g, k: 3 });
}

const PENTA = [523.25, 587.33, 659.25, 783.99, 880, 1046.5, 1174.66, 1318.51, 1567.98];

