/** 16비트 마감: 짧은 에코 → 살짝 찌그러뜨리기 → 해상도 낮추기 */
function finish(b: Buf, echo: number, delay: number) {
    if (echo > 0) {
        const d = Math.floor(delay * SR);
        let y = 0;
        for (let i = d; i < b.length; i++) {
            y += 0.5 * (b[i - d] - y); // 에코는 조금 먹먹하게
            b[i] += y * echo;
        }
    }
    const drive = 1.8, norm = Math.tanh(drive);
    const q = 128; // 8비트 단계로 깎아 거친 질감을 낸다
    for (let i = 0; i < b.length; i++) {
        // 두 샘플씩 같은 값을 유지해 16kHz 질감을 낸다
        const x = i % 2 ? b[i - 1] : Math.round(Math.max(-1, Math.min(1, Math.tanh(b[i] * drive) / norm)) * q) / q;
        b[i] = x;
    }
}

function render(r: Recipe): Buf {
    const delay = r.delay ?? 0.11;
    const b = new Float32Array(Math.ceil((r.len + (r.echo ? 0.5 : 0)) * SR));
    r.play(b);
    if (r.gain && r.gain !== 1) for (let i = 0; i < b.length; i++) b[i] *= r.gain;
    finish(b, r.echo ?? 0, delay);
    return b;
}

function play(c: AudioContext, data: Buf) {
    const buf = c.createBuffer(1, data.length, SR);
    buf.getChannelData(0).set(data);
    const src = c.createBufferSource();
    src.buffer = buf;
    src.connect(master!);
    src.start();
}

/** 연출 효과음 샘플만 만든다 (재생 없이). 검수용으로 WAV를 뽑을 때 쓴다 */
export function renderReveal(style: RevealStyle): { sampleRate: number; data: Float32Array } {
    return { sampleRate: SR, data: render(RECIPES[style]) };
}

// 연출이 시작되는 프레임에 계산하면 화면이 잠깐 멈추므로, 소리가 켜져 있으면 한가할 때 미리 만들어 둔다
const cache = new Map<RevealStyle, Buf>();
let warming = false;

function idle(f: () => void) {
    const ric = (window as Window & { requestIdleCallback?: (cb: () => void, o?: { timeout: number }) => number }).requestIdleCallback;
    if (ric) ric(f, { timeout: 2000 });
    else setTimeout(f, 50);
}

/** 소리가 켜져 있으면 모든 연출 효과음을 한가한 시간에 하나씩 미리 만든다 */
export function warmUpSounds() {
    if (typeof window === "undefined" || warming || !soundOn()) return;
    warming = true;
    const todo = (Object.keys(RECIPES) as RevealStyle[]).filter((s) => !cache.has(s));
    const step = () => {
        const s = todo.shift();
        if (!s || !soundOn()) {
            warming = false;
            return;
        }
        cache.set(s, render(RECIPES[s]));
        idle(step);
    };
    idle(step);
}

/** 등장 연출이 시작될 때 부른다. 소리가 꺼져 있거나 재생할 수 없으면 아무 일도 하지 않는다 */
export function playReveal(style: RevealStyle) {
    const c = audio();
    if (!c) return;
    play(c, cache.get(style) ?? render(RECIPES[style]));
}

/** 소리를 켰을 때 확인용 코인 소리 */
export function playToggleOn() {
    const c = audio();
    if (!c) return;
    play(
        c,
        render({
            len: 0.4,
            echo: 0.2,
            play: (b) => {
                blip(b, 0, 987.77, 0.06, 0.3, 0.5);
                blip(b, 0.06, 1318.51, 0.3, 0.3, 0.5);
            },
        }),
    );
}
