import { Link } from "react-router-dom";
import "./about.css";
import {
    CATEGORIES,
    HONOR_KIND_LABEL,
    PROFILE,
    SITE,
    formatHonorDate,
    getHonors,
    getProjectById,
    getProjectsByCategory,
    projectPath,
    projects,
} from "../content";
import type { Honor, ProfileEntry } from "../content";
import { CategoryBar } from "./index";
import { Rich } from "./rich";

/* ------------------------------------------------------------------ */
/* /awards — 수상·활동                                                   */
/* ------------------------------------------------------------------ */

function ProjectChip({ id, fallback }: { id?: string; fallback?: string }) {
    const p = id ? getProjectById(id) : undefined;
    if (p) {
        return (
            <Link to={projectPath(p)} className="ab-chip">
                {p.title} <span aria-hidden="true">→</span>
            </Link>
        );
    }
    return fallback ? <span className="ab-chip is-plain">{fallback}</span> : null;
}

function HonorItem({ h }: { h: Honor }) {
    const date = formatHonorDate(h);
    return (
        <li className={`ab-honor kind-${h.kind}`}>
            <div className="ab-honor-date">{date ?? "—"}</div>
            <div className="ab-honor-body">
                <h3 className="ab-honor-title">
                    <span className="ab-kind">{HONOR_KIND_LABEL[h.kind]}</span>
                    {h.title}
                    {h.result && <span className="ab-result">{h.result}</span>}
                </h3>
                {(h.org || h.team) && <p className="ab-honor-meta">{[h.org, h.team].filter(Boolean).join(" · ")}</p>}
                {h.description && <p className="ab-honor-desc">{h.description}</p>}
                <ProjectChip id={h.projectId} fallback={h.work} />
            </div>
        </li>
    );
}

export function AwardsPage() {
    const honors = getHonors();
    const top = honors.filter((h) => h.kind === "award" || h.kind === "selection");
    // 연도별로 묶는다 (시기가 없는 항목은 '그 외')
    const groups: { label: string; items: Honor[] }[] = [];
    for (const h of honors) {
        const label = h.date ? h.date.slice(0, 4) : "그 외";
        const g = groups.find((x) => x.label === label);
        if (g) g.items.push(h);
        else groups.push({ label, items: [h] });
    }
    return (
        <>
            <CategoryBar active="awards" />
            <div className="ab-page">
                <main className="ab-main">
                    <header className="ab-header">
                        <p className="ab-eyebrow">AWARDS &amp; ACTIVITIES</p>
                        <h1 className="ab-title">수상·활동</h1>
                        <p className="ab-lead">대회 수상, 선정, 멘토링 프로그램, 외주 개발 이력입니다. 결과가 확인된 것만 적었습니다.</p>
                    </header>

                    {top.length > 0 && (
                        <section aria-labelledby="ab-top">
                            <h2 className="ab-h2" id="ab-top">
                                주요 수상·선정
                            </h2>
                            <ul className="ab-trophies">
                                {top.map((h) => {
                                    const p = h.projectId ? getProjectById(h.projectId) : undefined;
                                    const inner = (
                                        <>
                                            <span className="ab-trophy-result">{h.result}</span>
                                            <span className="ab-trophy-title">{h.title}</span>
                                            <span className="ab-trophy-meta">{[h.date?.slice(0, 4), p?.title ?? h.work].filter(Boolean).join(" · ")}</span>
                                        </>
                                    );
                                    return (
                                        <li key={h.title} className={`ab-trophy kind-${h.kind}`}>
                                            {p ? <Link to={projectPath(p)}>{inner}</Link> : <div>{inner}</div>}
                                        </li>
                                    );
                                })}
                            </ul>
                        </section>
                    )}

                    <section aria-labelledby="ab-all">
                        <h2 className="ab-h2" id="ab-all">
                            전체 이력
                        </h2>
                        {groups.map((g) => (
                            <div key={g.label} className="ab-year">
                                <h3 className="ab-year-label">{g.label}</h3>
                                <ol className="ab-honors">
                                    {g.items.map((h) => (
                                        <HonorItem key={h.title + (h.date ?? "")} h={h} />
                                    ))}
                                </ol>
                            </div>
                        ))}
                    </section>
                </main>
            </div>
        </>
    );
}

/* ------------------------------------------------------------------ */
/* /profile — 프로필                                                     */
/* ------------------------------------------------------------------ */

function EntryList({ items }: { items: ProfileEntry[] }) {
    return (
        <ul className="ab-entries">
            {items.map((e) => {
                const p = e.projectId ? getProjectById(e.projectId) : undefined;
                return (
                    <li key={e.title} className="ab-entry">
                        <span className="ab-entry-period">{e.period}</span>
                        <span className="ab-entry-body">
                            <strong className="ab-entry-title">{e.title}</strong>
                            {e.detail && <span className="ab-entry-detail">{e.detail}</span>}
                            {p && (
                                <Link to={projectPath(p)} className="ab-chip">
                                    {p.title} <span aria-hidden="true">→</span>
                                </Link>
                            )}
                        </span>
                    </li>
                );
            })}
        </ul>
    );
}

export function ProfilePage() {
    const honors = getHonors();
    const awards = honors.filter((h) => h.kind === "award");
    const released = projects.filter((p) => p.status === "released").length;
    const featured = projects.filter((p) => p.featured).slice(0, 6);
    const stats = [
        { value: projects.length, label: "프로젝트" },
        { value: awards.length, label: "수상" },
        { value: honors.filter((h) => h.kind === "selection" || h.kind === "exhibition").length, label: "선정·출품" },
        { value: released, label: "스토어 출시" },
    ];
    return (
        <>
            <CategoryBar active="profile" />
            <div className="ab-page">
                <main className="ab-main">
                    <header className="ab-header ab-profile-head">
                        <p className="ab-eyebrow">PROFILE</p>
                        <h1 className="ab-title">{PROFILE.handle}</h1>
                        <p className="ab-name">
                            {PROFILE.name && <span>{PROFILE.name}</span>}
                            <span>{PROFILE.headline}</span>
                        </p>
                        <ul className="ab-social">
                            {SITE.social.map((s) => (
                                <li key={s.name}>
                                    <a href={s.url} target="_blank" rel="noreferrer">
                                        {s.name}
                                    </a>
                                </li>
                            ))}
                        </ul>
                    </header>

                    <section className="ab-intro" aria-label="소개">
                        {PROFILE.intro.map((t, i) => (
                            <p key={i}>
                                <Rich text={t} />
                            </p>
                        ))}
                    </section>

                    <ul className="ab-stats" aria-label="요약">
                        {stats.map((s) => (
                            <li key={s.label}>
                                <span className="ab-stat-value">{s.value}</span>
                                <span className="ab-stat-label">{s.label}</span>
                            </li>
                        ))}
                    </ul>

                    {PROFILE.ai && (
                        <section className="ab-ai" aria-labelledby="pf-ai">
                            <h2 className="ab-h2" id="pf-ai">
                                AI 활용 개발
                            </h2>
                            <p className="ab-ai-summary">{PROFILE.ai.summary}</p>
                            <ul className="ab-ai-tools">
                                {PROFILE.ai.tools.map((t) => (
                                    <li key={t.name}>
                                        <strong>{t.name}</strong>
                                        {t.detail && <span>{t.detail}</span>}
                                    </li>
                                ))}
                            </ul>
                            <ol className="ab-ai-practices">
                                {PROFILE.ai.practices.map((pr) => (
                                    <li key={pr.title}>
                                        <h3>{pr.title}</h3>
                                        <p>{pr.detail}</p>
                                        {pr.projectIds && (
                                            <p className="ab-ai-links">
                                                {pr.projectIds.map((id) => (
                                                    <ProjectChip key={id} id={id} />
                                                ))}
                                            </p>
                                        )}
                                    </li>
                                ))}
                            </ol>
                        </section>
                    )}

                    <div className="ab-cols">
                        <section aria-labelledby="pf-edu">
                            <h2 className="ab-h2" id="pf-edu">
                                학력
                            </h2>
                            <EntryList items={PROFILE.education} />
                        </section>
                        <section aria-labelledby="pf-aff">
                            <h2 className="ab-h2" id="pf-aff">
                                소속·활동
                            </h2>
                            <EntryList items={PROFILE.affiliations} />
                        </section>
                        {PROFILE.work.length > 0 && (
                            <section aria-labelledby="pf-work">
                                <h2 className="ab-h2" id="pf-work">
                                    외주
                                </h2>
                                <EntryList items={PROFILE.work} />
                            </section>
                        )}
                        <section aria-labelledby="pf-awards">
                            <h2 className="ab-h2" id="pf-awards">
                                수상
                            </h2>
                            <ul className="ab-entries">
                                {awards.map((h) => (
                                    <li key={h.title} className="ab-entry">
                                        <span className="ab-entry-period">{h.date?.slice(0, 4)}</span>
                                        <span className="ab-entry-body">
                                            <strong className="ab-entry-title">
                                                {h.title} {h.result}
                                            </strong>
                                            <ProjectChip id={h.projectId} />
                                        </span>
                                    </li>
                                ))}
                            </ul>
                            <Link to="/awards" className="ab-more">
                                수상·활동 전체 보기 <span aria-hidden="true">→</span>
                            </Link>
                        </section>
                    </div>

                    <section aria-labelledby="pf-skills">
                        <h2 className="ab-h2" id="pf-skills">
                            기술
                        </h2>
                        <dl className="ab-skills">
                            {PROFILE.skills.map((g) => (
                                <div key={g.group} className="ab-skill-row">
                                    <dt>{g.group}</dt>
                                    <dd>
                                        <ul>
                                            {g.items.map((s) => (
                                                <li key={s}>{s}</li>
                                            ))}
                                        </ul>
                                    </dd>
                                </div>
                            ))}
                        </dl>
                    </section>

                    <section aria-labelledby="pf-featured">
                        <h2 className="ab-h2" id="pf-featured">
                            대표 프로젝트
                        </h2>
                        <ul className="ab-featured">
                            {featured.map((p) => (
                                <li key={p.id}>
                                    <Link to={projectPath(p)}>
                                        <strong>{p.title}</strong>
                                        {p.subtitle && <span>{p.subtitle}</span>}
                                    </Link>
                                </li>
                            ))}
                        </ul>
                        <p className="ab-cats">
                            {CATEGORIES.map((c) => (
                                <Link key={c.id} to={projectPath(getProjectsByCategory(c.id)[0])} className="ab-chip is-cat">
                                    <img src={c.icon} alt="" /> {c.name} {getProjectsByCategory(c.id).length}
                                </Link>
                            ))}
                        </p>
                    </section>
                </main>
            </div>
        </>
    );
}
